/**
 * 스냅샷을 원자적으로 교체한다. **성공 여부를 돌려준다** — 호출측이 "새 복구 자료가 확실히 디스크에
 * 놓였을 때만 옛 복구 자료를 지운다" 는 순서를 지킬 수 있어야 하기 때문이다.
 * (예전에는 쓰기 실패를 경고만 하고 삼켰고, 그 뒤 `before-quit` 이 current.json 을 지워
 *  실패한 쓰기와 함께 세션이 통째로 사라질 수 있었다.)
 */
function writeSnapshot(target: string, snap: SessionSnapshot): boolean {
  const tmp = `${target}.tmp`
  try {
    mkdirSync(sessionsDir(), { recursive: true })
    writeFileSync(tmp, JSON.stringify(snap))
    renameSync(tmp, target) // 원자적 교체 (sync)
    return true
  } catch (err) {
    console.warn('[session] write failed', target, err)
    // 반쯤 쓰인 tmp 가 남으면 다음 쓰기의 rename 을 방해할 수 있다 — 치운다(원본은 건드리지 않는다).
    try { if (existsSync(tmp)) unlinkSync(tmp) } catch { /* best-effort */ }
    return false
  }
}

/**
 * 읽을 수 없는 스냅샷을 **지우지 않고 옆으로 치운다**. 이름을 고정해(타임스탬프 없이) 부팅마다
 * 손상본이 쌓이는 것을 막으면서도 원본 증거는 남긴다. 조용히 덮어쓰지 않는다 — 항상 로그를 남긴다.
 */
function preserveCorrupt(target: string, reason: string): void {
  const kept = `${target}.corrupt`
  try {
    try { if (existsSync(kept)) unlinkSync(kept) } catch { /* best-effort */ }
    renameSync(target, kept)
    console.warn(`[session] 손상된 스냅샷을 보존했습니다: ${kept} (${reason})`)
  } catch (err) {
    console.warn('[session] 손상 스냅샷 보존 실패', target, err)
  }
}

const RESTORABLE_URL = /^https?:|^browser:/i

/** 항목 하나가 이상하다고 나머지 멀쩡한 탭까지 버리지 않는다 — 못 쓰는 탭만 조용히 빠진다. */
function sanitizeTab(raw: unknown, fallbackIndex: number): SessionTabSnap | null {
  if (!raw || typeof raw !== 'object') return null
  const t = raw as Record<string, unknown>
  const url = typeof t.url === 'string' ? t.url : ''
  // collectSession 이 저장할 때 쓰는 것과 같은 규칙 — 여기서 넓히면 복원이 이상한 스킴을 열게 된다.
  if (!url || !RESTORABLE_URL.test(url)) return null
  const index = typeof t.index === 'number' && Number.isFinite(t.index) ? t.index : fallbackIndex
  const historyIndex = typeof t.historyIndex === 'number' && Number.isFinite(t.historyIndex)
    ? t.historyIndex : undefined
  const history = Array.isArray(t.history)
    ? (t.history.filter((e) => e && typeof e === 'object'
      && typeof (e as { url?: unknown }).url === 'string') as NavigationEntrySnap[])
    : undefined
  return {
    url,
    title: typeof t.title === 'string' ? t.title : url,
    pinned: t.pinned === true,
    workspaceId: typeof t.workspaceId === 'string' ? t.workspaceId : '',
    active: t.active === true,
    index,
    history: history && history.length > 0 ? history : undefined,
    historyIndex: history && history.length > 0 ? historyIndex : undefined,
    groupId: typeof t.groupId === 'string' ? t.groupId : undefined,
  }
}

function sanitizeBounds(raw: unknown): Electron.Rectangle | undefined {
  if (!raw || typeof raw !== 'object') return undefined
  const b = raw as Record<string, unknown>
  const nums = ['x', 'y', 'width', 'height'].map((k) => b[k])
  if (!nums.every((n) => typeof n === 'number' && Number.isFinite(n))) return undefined
  const [x, y, width, height] = nums as number[]
  if ((width as number) <= 0 || (height as number) <= 0) return undefined
  return { x: x as number, y: y as number, width: width as number, height: height as number }
}

function sanitizeWindow(raw: unknown): SessionWindowSnap | null {
  if (!raw || typeof raw !== 'object') return null
  const w = raw as Record<string, unknown>
  const rawTabs = Array.isArray(w.tabs) ? w.tabs : []
  const tabs: SessionTabSnap[] = []
  rawTabs.forEach((t, i) => { const ok = sanitizeTab(t, i); if (ok) tabs.push(ok) })
  if (tabs.length === 0) return null // 복원할 탭이 하나도 없는 창은 만들지 않는다
  return {
    windowId: typeof w.windowId === 'string' ? w.windowId : '',
    bounds: sanitizeBounds(w.bounds),
    activeTabId: typeof w.activeTabId === 'string' ? w.activeTabId : null,
    tabs,
    layouts: Array.isArray(w.layouts) ? (w.layouts as SessionWindowSnap['layouts']) : undefined,
    groups: Array.isArray(w.groups) ? (w.groups as SessionWindowSnap['groups']) : undefined,
  }
}

function readSnapshot(target: string): SessionSnapshot | null {
  if (!existsSync(target)) return null
  let parsed: unknown
  try {
    parsed = JSON.parse(readFileSync(target, 'utf-8'))
  } catch (err) {
    // 깨진 JSON(정전 중 반쯤 쓰인 파일 등) — 증거를 남기고 다른 스냅샷으로 넘어간다.
    preserveCorrupt(target, `JSON 파싱 실패: ${(err as Error).message}`)
    return null
  }
  if (!parsed || typeof parsed !== 'object') {
    preserveCorrupt(target, '최상위가 객체가 아님')
    return null
  }
  const snap = parsed as Record<string, unknown>
  if (snap.version !== SCHEMA_VERSION) {
    // 다른 버전은 "손상" 이 아니다 — 격리하지 않고 그냥 쓰지 않는다.
    console.warn(`[session] 스냅샷 스키마 불일치(${String(snap.version)}) — 무시: ${target}`)
    return null
  }
  if (!Array.isArray(snap.windows)) {
    preserveCorrupt(target, 'windows 가 배열이 아님')
    return null
  }
  const windows: SessionWindowSnap[] = []
  let dropped = 0
  for (const w of snap.windows) {
    const ok = sanitizeWindow(w)
    if (ok) windows.push(ok)
    else dropped += 1
  }
  if (dropped > 0) console.warn(`[session] 복원할 수 없는 창 ${dropped}개를 건너뜁니다: ${target}`)
  const savedAt = typeof snap.savedAt === 'number' && Number.isFinite(snap.savedAt) ? snap.savedAt : 0
  return { version: SCHEMA_VERSION, savedAt, windows }
}

