  for (const g of restored) {
    groups.set(g.id, { id: g.id, windowId, title: g.title, color: g.color, collapsed: !!g.collapsed })
    const m = /^group-(\d+)$/.exec(g.id)
    if (m) groupCounter = Math.max(groupCounter, Number(m[1]))
  }
}

