//  - softDueAt:       제목·파비콘·로딩 상태·창 크기. 합쳐도 되는 잡음성 변경.
// 예전에는 타이머가 하나뿐이라 잡음성 변경이 구조 변경의 1초 기한을 5초로 **다시 깔았다**.
// 페이지가 로딩되는 동안 제목·파비콘이 5초보다 자주 바뀌면 새 탭의 스냅샷이
// 30초 강제 저장 때까지 디스크에 닿지 않았고, 그 사이 크래시는 그 탭을 통째로 잃었다.
let structuralDueAt: number | null = null
let softDueAt: number | null = null

function armSaveTimer(): void {
  const due = Math.min(structuralDueAt ?? Infinity, softDueAt ?? Infinity)
  if (!Number.isFinite(due)) return
  if (saveTimer) clearTimeout(saveTimer)
  saveTimer = setTimeout(runScheduledSave, Math.max(0, due - Date.now()))
}

function runScheduledSave(): void {
  saveTimer = null
  structuralDueAt = null
  softDueAt = null
  if (restoring || quitting) return
  writeSnapshot(currentPath(), buildSnapshot())
}

function clearScheduledSave(): void {
  if (saveTimer) { clearTimeout(saveTimer); saveTimer = null }
  structuralDueAt = null
  softDueAt = null
}

/** 잡음성 변경(제목·파비콘·창 크기) — 마지막 것만 유효한 일반 디바운스. */
function scheduleSave(delay: number = SAVE_DEBOUNCE_MS): void {
  if (restoring || quitting) return // 종료 절차 중 탭 종료가 'list' 를 발화해 빈 스냅샷을 다시 쓰지 않도록
  softDueAt = Date.now() + delay
  armSaveTimer()
}

/** 구조 변경·내비게이션 — 한 번 잡힌 기한은 어떤 후속 이벤트로도 미뤄지지 않는다. */
function scheduleSaveSoon(): void {
  if (restoring || quitting) return
  const due = Date.now() + SAVE_SOON_MS
  structuralDueAt = structuralDueAt === null ? due : Math.min(structuralDueAt, due)
  armSaveTimer()
}

