function record(id, name, ok, detail) {
  checks.push({ id, name, status: ok ? 'PASS' : 'FAIL', detail: String(detail) })
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${id}  ${name}\n      ${detail}`)
