    if (tabs.length >= n) return tabs
    await sleep(300)
  }
  throw new Error('timeout waiting tabs')
}
async function waitLoaded(tabId, prefix, timeoutMs) {
  const start = Date.now()
  while (Date.now()-start < timeoutMs) {
    const tabs = await ev(\`window.browserAPI.tabs.list(\${JSON.stringify(windowId)})\`)
    const t = tabs.find(x=>x.id===tabId)
    if (t && !t.loading && t.url && t.url.startsWith(prefix)) return t
