function runScheduledSave(): void {
  saveTimer = null
  const now = Date.now()
  // 지금 도래한 기한만 소비한다 — 아직 오지 않은 "가라앉은 뒤의 저장" 은 그대로 둔다.
  deadlines.consumeDue(now)
  if (restoring || quitting) { deadlines.clear(); return }
  writeSnapshot(currentPath(), buildSnapshot())
  // 이 저장은 탭 목록을 지키려고 일찍 뜬 것이라 스크롤·폼(pageState)이 아직 낡아 있을 수 있다.
  // 활동이 잦아든 뒤 한 번 더 떠서 가라앉은 상태를 담는다. 매 이벤트마다 쓰는 것이 아니라
  // **활동 묶음당 최대 두 번**이다.
  deadlines.ensureSoft(now, SAVE_DEBOUNCE_MS)
  armSaveTimer()
}

