  const hasScroll = win.tabs.some((t) => t.url === probe.scrollUrl)
  return (hasT7 && hasScroll) ? snap : null
}, { timeoutMs: 40_000, intervalMs: 500, label: 'sessions/current.json 에 정착 후 스냅샷(T7+scroll) flush' })

