  } finally {
    if (launch2) {
      try { launch2.chromeSession.close() } catch { /* ignore */ }
      await gracefulThenForceKill(launch2.child, args.port, args.out)
    }
    if (launch1 && isPidAlive(launch1.child.pid)) killPidTree(launch1.child.pid)
